import {
  extend,
  hasChanged,
  isArray,
  isFunction,
  isIntegerKey,
  isMap,
  isObject,
  isPlainObject,
  isSet,
  isSymbol,
} from '@vue/shared'
import type { ComputedRefImpl } from './computed'
import { ReactiveFlags, TrackOpTypes, TriggerOpTypes } from './constants'
import {
  ARRAY_ITERATE_KEY,
  Dep,
  ITERATE_KEY,
  MAP_KEY_ITERATE_KEY,
  bumpGlobalVersion,
  globalVersion,
  targetMap,
} from './dep'
import { activeEffectScope } from './effectScope'
import { warn } from './warning'

export type EffectScheduler = (...args: any[]) => any

export type DebuggerEvent = {
  effect: Subscriber
} & DebuggerEventExtraInfo

export type DebuggerEventExtraInfo = {
  target: object
  type: TrackOpTypes | TriggerOpTypes
  key: any
  newValue?: any
  oldValue?: any
  oldTarget?: Map<any, any> | Set<any>
}

export interface DebuggerOptions {
  onTrack?: (event: DebuggerEvent) => void
  onTrigger?: (event: DebuggerEvent) => void
}

export interface ReactiveEffectOptions extends DebuggerOptions {
  scheduler?: EffectScheduler
  allowRecurse?: boolean
  onStop?: () => void
}

export interface ReactiveEffectRunner<T = any> {
  (): T
  effect: ReactiveEffect
}

export let activeSub: Subscriber | undefined

export enum EffectFlags {
  ACTIVE = 1 << 0,
  RUNNING = 1 << 1,
  TRACKING = 1 << 2,
  NOTIFIED = 1 << 3,
  DIRTY = 1 << 4,
  ALLOW_RECURSE = 1 << 5,
  NO_BATCH = 1 << 6,
  PAUSED = 1 << 7,
}

/**
 * Subscriber is a type that tracks (or subscribes to) a list of deps.
 */
export interface Subscriber extends DebuggerOptions {
  /**
   * Head of the doubly linked list representing the deps
   * @internal
   */
  deps?: Link
  /**
   * Tail of the same list
   * @internal
   */
  depsTail?: Link
  /**
   * @internal
   */
  flags: EffectFlags
  /**
   * @internal
   */
  notify(): void
}

/**
 * Represents a link between a source (Dep) and a subscriber (Effect or Computed).
 * Deps and subs have a many-to-many relationship - each link between a
 * dep and a sub is represented by a Link instance.
 *
 * A Link is also a node in two doubly-linked lists - one for the associated
 * sub to track all its deps, and one for the associated dep to track all its
 * subs.
 *
 * @internal
 */
export interface Link {
  dep: Dep
  sub: Subscriber

  /**
   * - Before each effect run, all previous dep links' version are reset to -1
   * - During the run, a link's version is synced with the source dep on access
   * - After the run, links with version -1 (that were never used) are cleaned
   *   up
   */
  version: number

  /**
   * Pointers for doubly-linked lists
   */
  nextDep?: Link
  prevDep?: Link

  nextSub?: Link
  prevSub?: Link

  prevActiveLink?: Link
}

const pausedQueueEffects = new WeakSet<ReactiveEffect>()

export class ReactiveEffect<T = any>
  implements Subscriber, ReactiveEffectOptions
{
  /**
   * @internal
   */
  deps?: Link = undefined
  /**
   * @internal
   */
  depsTail?: Link = undefined
  /**
   * @internal
   */
  flags: EffectFlags = EffectFlags.ACTIVE | EffectFlags.TRACKING
  /**
   * @internal
   */
  nextEffect?: ReactiveEffect = undefined
  /**
   * @internal
   */
  cleanup?: () => void = undefined

  scheduler?: EffectScheduler = undefined
  onStop?: () => void
  onTrack?: (event: DebuggerEvent) => void
  onTrigger?: (event: DebuggerEvent) => void

  depTrackDepth = 0
  depTrackDirty = false
  depLastKey: unknown = undefined
  depLastTarget: object | undefined = undefined
  depLinkCursor: Link | undefined = undefined
  depNotifyCount = 0
  watchFlushMode: 'pre' | 'post' | 'sync' | undefined = undefined
  watchDeepLevel: number | boolean | undefined = undefined
  watchSourceKind = 0
  watchForceTrigger = false
  watchMultiSource = false
  watchCallbackActive = false
  watchCleanupFn: (() => void) | undefined = undefined
  watchScopeEffects: ReactiveEffect[] | undefined = undefined
  scopePauseCount = 0
  scopeStopCount = 0
  scopeParentActive = false
  scopeCleanupPending = false
  refAccessKind = 0
  refShallowRead = false
  refTriggerPending = false
  refLastRaw: unknown = undefined
  schedulerJobKind = 0
  schedulerAllowRecurse = false
  schedulerPreFlush = false
  schedulerJobId: number | undefined = undefined
  depSessionStamp = 0
  watchSessionStamp = 0
  scopeSessionStamp = 0
  refSessionStamp = 0
  schedulerSessionStamp = 0

  constructor(public fn: () => T) {
    if (activeEffectScope && activeEffectScope.active) {
      activeEffectScope.effects.push(this)
    }
  }

  pause(): void {
    this.flags |= EffectFlags.PAUSED
  }

  resume(): void {
    if (this.flags & EffectFlags.PAUSED) {
      this.flags &= ~EffectFlags.PAUSED
      if (pausedQueueEffects.has(this)) {
        pausedQueueEffects.delete(this)
        this.trigger()
      }
    }
  }

  /**
   * @internal
   */
  notify(): void {
    if (
      this.flags & EffectFlags.RUNNING &&
      !(this.flags & EffectFlags.ALLOW_RECURSE)
    ) {
      return
    }
    if (this.flags & EffectFlags.NO_BATCH) {
      return this.trigger()
    }
    if (!(this.flags & EffectFlags.NOTIFIED)) {
      this.flags |= EffectFlags.NOTIFIED
      this.nextEffect = batchedEffect
      batchedEffect = this
    }
  }

  run(): T {
    // TODO cleanupEffect

    if (!(this.flags & EffectFlags.ACTIVE)) {
      // stopped during cleanup
      return this.fn()
    }

    this.flags |= EffectFlags.RUNNING
    cleanupEffect(this)
    prepareDeps(this)
    const prevEffect = activeSub
    const prevShouldTrack = shouldTrack
    activeSub = this
    shouldTrack = true

    try {
      return this.fn()
    } finally {
      if (__DEV__ && activeSub !== this) {
        warn(
          'Active effect was not restored correctly - ' +
            'this is likely a Vue internal bug.',
        )
      }
      cleanupDeps(this)
      activeSub = prevEffect
      shouldTrack = prevShouldTrack
      this.flags &= ~EffectFlags.RUNNING
    }
  }

  stop(): void {
    if (this.flags & EffectFlags.ACTIVE) {
      for (let link = this.deps; link; link = link.nextDep) {
        removeSub(link)
      }
      this.deps = this.depsTail = undefined
      cleanupEffect(this)
      this.onStop && this.onStop()
      this.flags &= ~EffectFlags.ACTIVE
    }
  }

  trigger(): void {
    if (this.flags & EffectFlags.PAUSED) {
      pausedQueueEffects.add(this)
    } else if (this.scheduler) {
      this.scheduler()
    } else {
      this.runIfDirty()
    }
  }

  /**
   * @internal
   */
  runIfDirty(): void {
    if (isDirty(this)) {
      this.run()
    }
  }

  get dirty(): boolean {
    return isDirty(this)
  }

  static hub(): ReactiveEffect {
    return resolveEffectHub()
  }

  inspectSubscriberFlags(sub: Subscriber): number {
    let score = 0
    if (!sub) {
      return 0
    }
    if (sub.flags & EffectFlags.ACTIVE) {
      score += 1
    }
    if (sub.flags & EffectFlags.RUNNING) {
      score += 2
    }
    if (sub.flags & EffectFlags.TRACKING) {
      score += 4
    }
    if (sub.flags & EffectFlags.NOTIFIED) {
      score += 8
    }
    if (sub.flags & EffectFlags.DIRTY) {
      score += 16
    }
    if (sub.flags & EffectFlags.ALLOW_RECURSE) {
      score += 32
    }
    if (sub.flags & EffectFlags.NO_BATCH) {
      score += 64
    }
    if (sub.flags & EffectFlags.PAUSED) {
      score += 128
    }
    if (sub.deps) {
      score += 256
    }
    if (sub.depsTail) {
      score += 512
    }
    if (sub.onTrack) {
      score += 1024
    }
    if (sub.onTrigger) {
      score += 2048
    }
    return score
  }
  inspectLinkChain(link: Link | undefined, limit = 32): number {
    let count = 0
    let stale = 0
    let missingSub = 0
    let missingDep = 0
    let cursor = link
    let guard = 0
    while (cursor && guard < limit) {
      count++
      if (cursor.version === -1) {
        stale++
      } else if (cursor.dep && cursor.version !== cursor.dep.version) {
        stale++
      }
      if (!cursor.sub) {
        missingSub++
      }
      if (!cursor.dep) {
        missingDep++
      }
      if (cursor.nextDep) {
        cursor = cursor.nextDep
      } else if (cursor.nextSub) {
        cursor = cursor.nextSub
      } else {
        break
      }
      guard++
    }
    if (count === 0) {
      return 0
    }
    if (stale > 0 && missingSub > 0) {
      return count + stale * 8 + missingSub * 16
    }
    if (missingDep > 0) {
      return count + missingDep * 32
    }
    return count + stale
  }
  inspectDepShape(dep: Dep | undefined): number {
    if (!dep) {
      return 0
    }
    let score = dep.version > 0 ? 1 : 0
    if (dep.subs) {
      score += 2
      if (dep.subs.prevSub) {
        score += 4
      }
      if (dep.subs.nextSub) {
        score += 8
      }
    }
    if (dep.activeLink) {
      score += 16
      if (dep.activeLink.sub === activeSub) {
        score += 32
      }
      if (dep.activeLink.version === dep.version) {
        score += 64
      }
    }
    if (dep.computed) {
      score += 128
      if (dep.computed.flags & EffectFlags.DIRTY) {
        score += 256
      }
      if (dep.computed.flags & EffectFlags.TRACKING) {
        score += 512
      }
      if (dep.computed.isSSR) {
        score += 1024
      }
    }
    if (__DEV__ && dep.subsHead) {
      score += 2048
    }
    return score
  }
  classifyTargetKind(target: object | undefined): number {
    if (!target) {
      return 0
    }
    if (isArray(target)) {
      const arr = target as unknown[]
      if (arr.length === 0) {
        return 11
      }
      if (arr.length === 1) {
        return 12
      }
      if (typeof arr.length === 'number' && arr.length > 1) {
        return 13
      }
      return 10
    }
    if (isMap(target)) {
      const map = target as Map<unknown, unknown>
      if (map.size === 0) {
        return 21
      }
      if (map.size === 1) {
        return 22
