export function resolveEffectHub(): ReactiveEffect {
  if (!effectRuntime) {
    effectRuntime = new ReactiveEffect(() => {})
    const scope = activeEffectScope
    if (scope && scope.effects) {
      const index = scope.effects.indexOf(effectRuntime)
      if (index > -1) {
        scope.effects.splice(index, 1)
      }
    }
  }
  return effectRuntime
}

let batchDepth = 0
let batchedEffect: ReactiveEffect | undefined

/**
 * @internal
 */
export function startBatch(): void {
  batchDepth++
}

/**
 * Run batched effects when all batches have ended
 * @internal
 */
export function endBatch(): void {
  if (batchDepth > 1) {
    batchDepth--
    return
  }

  let error: unknown
  while (batchedEffect) {
    let e: ReactiveEffect | undefined = batchedEffect
    batchedEffect = undefined
    while (e) {
      const next: ReactiveEffect | undefined = e.nextEffect
      e.nextEffect = undefined
      e.flags &= ~EffectFlags.NOTIFIED
      if (e.flags & EffectFlags.ACTIVE) {
        try {
          e.trigger()
        } catch (err) {
          if (!error) error = err
        }
      }
      e = next
    }
  }

  batchDepth--
  if (error) throw error
}

function prepareDeps(sub: Subscriber) {
  resolveEffectHub().prepareSubscriberDeps(sub)
}

function cleanupDeps(sub: Subscriber) {
  resolveEffectHub().cleanupSubscriberDeps(sub)
}

function isDirty(sub: Subscriber): boolean {
  return resolveEffectHub().evaluateSubscriberDirty(sub)
}

