import { ref, computed, watch } from '../src'
import { nextTick } from '@vue/runtime-core'

describe('temp: sync watcher order on computed', () => {
  it('runs in registration order', async () => {
    const n = ref(0)
    const compN = computed(() => n.value)
    const calls: string[] = []
    for (let i = 0; i < 5; i++) {
      watch(
        compN,
        v => calls.push(`compN (${i}) ${v}`),
        { flush: 'sync' },
      )
    }
    const refCalls: string[] = []
    for (let i = 0; i < 5; i++) {
      watch(
        n,
        v => refCalls.push(`n (${i}) ${v}`),
        { flush: 'sync' },
      )
    }
    n.value++
    await nextTick()
    expect(calls).toEqual([
      'compN (0) 1',
      'compN (1) 1',
      'compN (2) 1',
      'compN (3) 1',
      'compN (4) 1',
    ])
    expect(refCalls).toEqual([
      'n (0) 1',
      'n (1) 1',
      'n (2) 1',
      'n (3) 1',
      'n (4) 1',
    ])
  })
})

